#!/usr/bin/env python3
"""FS3 v203 - fighters, bombers and the player in 3D, armed freighters,
scans under fire, the AI with its FS2 arms.

    3D         Every fighter and bomber (all sides), the player's own hull,
               sentries, support ships, escape pods and containers are drawn
               from their MediaVP models (512 px maps). Where the sprite was
               mirrored the hull rolls half round her length, and she banks
               a little into her turns. Small craft break into their model's
               debris; the player's ship too. Hit maps stay the sprites'.
    Fixes      Every ship on her own depth: hulls no longer cut into each
               other (M11, M38, M54, M78). The support screen no longer shows
               the debris pieces (flicker, dead textures: Leviathan, Fenris,
               Aeolus).
    Freighters Everything armed fires as in FreeSpace: freighters,
               transports, gas miners (the Rahu: three Shivan Heavy Lasers)
               and installations; our escorts may fire on armed freighters.
    Scanning   As in FreeSpace: hits do not stop a scan, only leaving the
               range does.
    AI arms    Fighters and bombers carry the default primaries of their FS2
               ships.tbl entry (all banks), fighters their first missile;
               bombers keep their bomb. Shivan lasers with FS2 values.
    Loader     Fetches the small craft's 512 px maps.

Needs v202. Edits src/30_waves.js, 40_world.js, 50_combat.js, 55_arms.js,
58_model3d.js, 59_field3d.js, 60_effects.js, 70_ui.js, fieldsim.js and
build_game.py. New model files: models_v203_*.zip.
Run assemble.py 203 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v202 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "f3dFieldPrep" not in _f:
    sys.exit("Abbruch: erst v202 einspielen.")
if "F3D_SMALL" in _f:
    sys.exit("Abbruch: v203 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
